  function norm(s) {
    return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]/g, "");
  }

  window.resolveCopilotPlayer = function(text) {
    if (!text || typeof text !== "string") return null;
    const raw = text.trim();
    if (!raw || raw.length < 3) return null;

    // 1. Direct normalized match
    const n = norm(raw);
    if (window.COPILOT_PLAYER_MAP[n]) return window.COPILOT_PLAYER_MAP[n];

    // 2. Clean common prefixes and suffixes (e.g. "1. Connor McDavid (EDM - C)", "C. Makar, D")
    let cleaned = raw.replace(/^(?:pick\s*\d+[:\.\s]*|round\s*\d+[:\.\s]*|\d+[\.\:\s]+)/i, "").trim();
    cleaned = cleaned.split(/ - | \(|\s*,\s*[A-Z]{2,3}\b|\n/)[0].trim();
    cleaned = cleaned.replace(/\s+(?:IR|IR-LT|DTD|OUT|O|SSPD|NA|C|LW|RW|F|D|G)$/i, "").trim();
    const nCleaned = norm(cleaned);
    if (window.COPILOT_PLAYER_MAP[nCleaned]) return window.COPILOT_PLAYER_MAP[nCleaned];

    // 3. Substring match against full names
    for (let i = 0; i < window.COPILOT_PLAYER_LIST.length; i++) {
      const pName = window.COPILOT_PLAYER_LIST[i];
      if (raw.includes(pName)) return pName;
    }

    return null;
  };
